async _actionAuthResult({ status }) {
  switch (status) {
    case AUTH_ACCEPTED:
      this._authenticated = true;
      this._currentAction?.();
      return;
    case AUTH_PASSWORD_REQUIRED:
      this._actionAuthPassword();
      return;
    case AUTH_FAILED: {
      const action = this._authenticator.promptAuthFailed(this._msgWindow);
      if (action == 1) {
        // Cancel button pressed.
        this._actionDone();
        return;
      }
      if (action == 2) {
        // 'New password' button pressed.
        const signonUrl = this._newsFolder.urlForSignon;

        // There should only be one login stored for this url, however just in case
        // there isn't.
        for (const login of await Services.logins.searchLoginsAsync({
          origin: Services.io.newURI(signonUrl).prePath,
          httpRealm: signonUrl,
        })) {
          await Services.logins.removeLoginAsync(login);
        }

        // Clear out the saved passwords for anyone else who tries to call.
        this._newsFolder.groupUsername = "";
        this._newsFolder.groupPassword = "";
      }
      // Retry.
      this._actionAuthUser();
    }
  }
